cfg=re.sub(r'^SEED_VERSION\s*=\s*".*?"','SEED_VERSION = "v130.1-ui"',cfg,flags=re.M)
for name in ["SEED_V1301_UI_UX_OVERHAUL","SEED_V1291_AVATAR2_POLISH","SEED_V106_UI_CONTROL_ROOM"]:
    if name not in cfg:
        cfg += f"\n{name} = True"
cfgp.write_text(cfg+"\n")
